func:
// Écran de la tablette : éteint de 23h00 à 7h15 (heure de Paris), via ADB (intégration Android Debug Bridge).
// (La commande d'extinction de l'application Home Assistant ne marche pas sur cet Android.)
// Appelé chaque minute : on n'envoie une commande que si l'état voulu a changé.
const OFF = '23:00', ON = '07:15';
const TABLETTE = 'media_player.android_tv_192_168_1_75';
const p = {};
new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(new Date()).forEach(x => { p[x.type] = x.value; });
const hm = `${p.hour}:${p.minute}`;
const voulu = msg.forcer || ((hm >= OFF || hm < ON) ? 'off' : 'on');
if (!msg.forcer && flow.get('ecran') === voulu) { return null; }
if (!msg.forcer) { flow.set('ecran', voulu); }
node.status({ fill: voulu === 'off' ? 'grey' : 'yellow', shape: 'dot', text: `écran ${voulu === 'off' ? 'éteint' : 'allumé'} (${hm})` });
msg.payload = { action: 'androidtv.adb_command', data: { entity_id: TABLETTE, command: voulu === 'off' ? 'input keyevent 223' : 'input keyevent 224; sleep 1; input keyevent 82; am start -a android.intent.action.VIEW -d homeassistant://navigate/dashboard-maison/ensemble io.homeassistant.companion.android' } };
return msg;

// Alerte : le lien ADB avec la tablette est perdu (tablette redémarrée ?), donc l'écran ne s'éteindra plus.
// Une seule alerte tant que le problème dure ; elle se ré-arme quand le lien revient.
const hors = msg.error || msg.payload === 'unavailable';
if (!hors) {
    flow.set('adbAlerte', false);
    node.status({ fill: 'green', shape: 'dot', text: 'ADB ok (' + msg.payload + ')' });
    return null;
}
if (flow.get('adbAlerte') && !msg.test) {
    node.status({ fill: 'grey', shape: 'ring', text: 'ADB hors ligne (déjà signalé)' });
    return null;
}
if (!msg.test) { flow.set('adbAlerte', true); }
node.status({ fill: 'red', shape: 'dot', text: 'ADB hors ligne : alerte envoyée' });
const titre = 'Tablette : ADB hors ligne';
const texte = "Le lien ADB avec la tablette est perdu : l'écran ne s'éteindra plus. Rebranche la tablette en USB à un PC et relance adb tcpip 5555.";
return [
    { payload: { action: 'notify.mobile_app_tablette', data: { title: titre, message: texte } } },
    { payload: { action: 'notify.persistent_notification', data: { title: titre, message: texte } } }
];
